import{_ as o,o as r,c,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"ADR-001 — Polyrepo (nhiều repo riêng biệt)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-001-polyrepo.md","filePath":"adr/ADR-001-polyrepo.md"}'),n={name:"adr/ADR-001-polyrepo.md"};function t(a,e,s,d,p,l){return r(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-001-—-polyrepo-nhieu-repo-rieng-biet" tabindex="-1">ADR-001 — Polyrepo (nhiều repo riêng biệt) <a class="header-anchor" href="#adr-001-—-polyrepo-nhieu-repo-rieng-biet" aria-label="Permalink to &quot;ADR-001 — Polyrepo (nhiều repo riêng biệt)&quot;">​</a></h1><p><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>BrandHub gồm 7 thành phần độc lập: <code>api-gateway</code>, <code>business-service</code>, <code>ai-service</code>, <code>publisher-service</code>, <code>web-dashboard</code>, <code>mobile-app</code>, <code>infrastructure</code>. Cần quyết định: 1 monorepo chứa tất cả, hay polyrepo (mỗi thành phần 1 GitHub repo riêng).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Dùng <strong>polyrepo</strong> — 7 repo riêng biệt dưới cùng 1 GitHub Organization (<code>BrandHubOrganization</code>), quản lý chung qua <code>brandhub-infrastructure</code> (docs, docker-compose, scripts liên service).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Tích cực:</strong></p><ul><li>Ngôn ngữ/stack khác nhau (Java Spring Boot, Python FastAPI, TypeScript React) tách CI/CD riêng, không phụ thuộc build tool chung.</li><li>Team 5 người, mỗi người chủ yếu chạm 1-2 repo — giảm conflict PR, review scope rõ ràng theo service.</li><li>Version độc lập từng service — deploy <code>publisher-service</code> không kéo theo rebuild <code>web-dashboard</code>.</li></ul><p><strong>Tiêu cực:</strong></p><ul><li>Thay đổi cross-service (vd: đổi RabbitMQ message schema) cần PR đồng bộ ở 2 repo (<code>business-service</code> + <code>publisher-service</code>) — không atomic commit.</li><li>Không có single source of truth cho dependency version giữa các service — <code>brandhub-infrastructure/docs/architecture/</code> đóng vai trò tài liệu điều phối thủ công.</li><li>Local dev cần clone 7 repo, <code>docker-compose.apps.yml</code> build từ Dockerfile sibling repo (<code>../../brandhub-*</code>) — setup ban đầu phức tạp hơn monorepo.</li></ul>',11)])])}const g=o(n,[["render",t]]);export{u as __pageData,g as default};
